def __getitem__(self, item):
    if isinstance(item, int):
        return self.fixed[item]
    elif isinstance(item, slice):
        # Handle slice access for R10
        return Result(
            fixed=self.fixed[item],
            named=self.named,
            spans={k: v[item] if isinstance(v, tuple) and len(v) == 2 else v 
                   for k, v in self.spans.items()}
        )
    return self.named[item]

def __contains__(self, item):
    """Check if a value is present in the parsed results (R2)."""
    return item in self.fixed or item in self.named.values()

